// Today's date in the format the admin user's language expects (this instance is
// dd/mm/yyyy; en_US would be mm/dd/yyyy) — typing the wrong order is silently rejected.
async function todayInUserFormat(rpc: { searchRead: Function; read: Function }): Promise<string> {
  const [user] = await rpc.read("res.users", [2], ["lang"]);
  const [lang] = await rpc.searchRead("res.lang", [["code", "=", user.lang]], ["date_format"], { limit: 1 });
  const d = new Date();
  const parts: Record<string, string> = {
    "%d": String(d.getDate()).padStart(2, "0"),
    "%m": String(d.getMonth() + 1).padStart(2, "0"),
    "%Y": String(d.getFullYear()),
  };
  return (lang?.date_format ?? "%m/%d/%Y").replace(/%[dmY]/g, (t: string) => parts[t] ?? t);
}

// Type into a many2one autocomplete and pick the match. Odoo 17 highlights the FIRST option
// automatically, so a plain Enter selects it — an extra ArrowDown would land on "Search More...".
async function pickOption(page: Page, input: Locator, text: string, optionText: string) {
  await input.click();
  await input.fill("");
  await input.fill(text);
  const option = page.locator(".o-autocomplete--dropdown-item").filter({ hasText: optionText }).first();
  await option.waitFor({ state: "visible", timeout: 15000 });
  await page.keyboard.press("Enter");
  await expect(input).toHaveValue(new RegExp(optionText, "i"), { timeout: 10000 });
}

// Screenshot the current page with the target element outlined.
async function shot(page: Page, loc: Locator, file: string) {
  try {
    await loc.scrollIntoViewIfNeeded({ timeout: 5000 });
    await loc.evaluate((el) => el.setAttribute("data-t2p", "1"));
    await page.addStyleTag({
      content: '[data-t2p="1"]{outline:3px solid #e01e5a !important;outline-offset:2px !important;}',
    });
  } catch {}
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/${file}` });
  try { await loc.evaluate((el) => el.removeAttribute("data-t2p")); } catch {}
}

